{
  "description": "The creature is shown in right-facing side profile standing on a small patch of rocky ground. It has the overall size and proportions of a small, stocky horse or pony. The head, neck, lower legs, and tail are covered in shaggy brown fur with a horse-like appearance, while the entire torso, back, sides, and belly are bare and covered in thick, warty, mottled skin in dark blue-grey, brown, and pale cream with many raised bumps. The boundary between the furry and bare areas is abrupt at the base of the neck, the chest, and the upper legs. The animal stands on four legs and has a long, hairy tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a horse's head, brown with a lighter tan muzzle, a large dark nostril, a dark eye with a visible eyelid, and a closed mouth with short whiskers on the chin and muzzle",
      "where": "at the front top of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, furry brown horse ears with darker inner edges",
      "where": "on top of the head, one slightly behind the other"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, uneven brown fur with darker streaks, longer and coarser than the body fur",
      "where": "running along the top of the neck from just behind the ears down to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, columnar, horse-like legs covered in long shaggy brown fur with visible joints at the knee/hock",
      "where": "two forelegs under the chest and two hind legs under the rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four single, rounded, dark brown hooves with a hard outer wall",
      "where": "at the bottom tip of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, straight, dense horse tail made of long brown hair",
      "where": "hanging down from the rump at the rear left of the body"
    },
    {
      "part": "scales",
      "looks_like": "bare, thick, amphibian-like skin with a bumpy, warty texture, not fur or feathers; dark mottled blue-grey and brown on the back and sides fading to pale cream and wrinkled on the belly, covered in many small and large raised round tubercles",
      "where": "covering the entire torso, back, flanks, and underbelly between the furry neck/chest and the furry upper legs"
    },
    {
      "part": "markings",
      "looks_like": "irregular mottled patches of dark grey, blue, brown, and off-white on the bare skin, plus scattered light and dark wart-like spots",
      "where": "across the bare skin of the back, sides, and belly"
    }
  ],
  "attached_objects": [],
  "animals": ["horse", "toad"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
